<template>
  <div :class="['detail-page', isSalesView ? 'detail-page--sales' : 'detail-page--procurement']" v-loading="loading">
    <div class="back-row">
      <el-button link class="back" @click="router.push(listPath)">← {{ isSalesView ? '返回客户询盘项目' : '返回采购寻源项目' }}</el-button>
    </div>
    <template v-if="detail">
      <header class="hero">
        <div><span class="detail-perspective">{{ isSalesView ? '销售 · 客户协作' : '采购 · 寻源执行' }}</span><small>{{ isSalesView ? '客户询盘' : '寻源任务' }} · {{ detail.caseNo }}</small><h1>{{ detail.title || '未命名询盘项目' }}</h1><p>客户 {{ detail.customerName || '未关联' }} · 联系人 {{ detail.contactName || detail.contactEmail || '—' }} · 负责人 {{ detail.ownerName || '—' }} · 来源 {{ detail.sourceMailId ? '邮件转入' : '员工录入' }}</p></div>
        <div class="hero-actions"><el-button v-if="canOpenPeer" @click="openPeerView">{{ isSalesView ? '查看采购寻源' : '查看客户询盘' }}</el-button><el-button v-if="detail.sourceMailId" @click="openSourceMail">查看来源邮件</el-button><el-button v-if="detail.sourceFileUrl" @click="openSourceFile">下载原始询盘</el-button><el-tag size="large" effect="dark">{{ statusLabel(detail.status) }}</el-tag></div>
      </header>
      <section class="progress-card">
        <div v-for="(item,index) in stages" :key="item.key" :class="['stage',{active:index<=stageIndex}]"><b>{{ index+1 }}</b><span>{{ item.label }}</span></div>
        <aside><small>当前待办</small><strong>{{ waitingText }}</strong></aside>
      </section>

      <section class="content-card">
        <el-tabs v-model="tab" @tab-change="loadTab">
          <el-tab-pane :label="isSalesView ? '客户需求' : '需求快照'" name="products">
            <div class="section-head"><div><h2>{{ isSalesView ? '客户需求' : '采购需求快照' }}</h2><p>{{ isSalesView ? '保留销售复核后的客户需求，采购与销售查看的是同一份数据。' : '销售已完成需求复核；采购据此联系供应商并形成成本方案。' }}</p></div><el-tag type="success" effect="plain">询盘已人工复核</el-tag></div>
            <el-table :data="rfqEligibleLines" row-key="id">
              <el-table-column prop="lineNo" label="#" width="55" />
              <el-table-column label="产品与标准" min-width="260"><template #default="{row}"><strong>{{ row.extracted.product||'—' }}</strong><small>{{ [row.extracted.materialStandard,row.extracted.grade].filter(Boolean).join(' / ')||'—' }}</small></template></el-table-column>
              <el-table-column label="模板规格" min-width="300"><template #default="{row}"><span class="spec-summary">{{ specificationSummary(row.extracted) }}</span></template></el-table-column>
              <el-table-column label="数量" width="130"><template #default="{row}">{{ row.extracted.quantity||'—' }} {{ row.extracted.quantityUnit }}</template></el-table-column>
              <el-table-column label="来源" width="130"><template #default><el-tag type="success" effect="plain">询盘复核通过</el-tag></template></el-table-column>
            </el-table>
          </el-tab-pane>

          <el-tab-pane v-if="isSalesView" label="采购进度" name="procurementProgress">
            <div class="section-head"><div><h2>采购进度摘要</h2><p>这里只展示协同进度，不展示供应商底价和采购操作。</p></div><el-button link type="primary" @click="openPeerView">进入采购寻源视角</el-button></div>
            <div class="perspective-summary"><div><small>当前阶段</small><strong>{{ statusLabel(detail.status) }}</strong></div><div><small>已发起询价</small><strong>{{ rfqs.length }}</strong></div><div><small>已收到报价</small><strong>{{ quotedRfqCount }}</strong></div><div><small>已确认报价依据</small><strong>{{ confirmedCosts.length }}</strong></div></div>
          </el-tab-pane>

          <el-tab-pane v-if="isSalesView" label="报价依据" name="quotationBasis">
            <div class="section-head"><div><h2>已确认报价依据</h2><p>采购确认后供销售生成客户报价；供应商底价和费用明细不在销售视角展示。</p></div></div>
            <el-table :data="confirmedCosts"><el-table-column label="方案版本" width="210"><template #default="{row}"><strong>V{{ row.versionNo || 1 }}</strong><small>{{ row.scenarioNo }}</small></template></el-table-column><el-table-column prop="currency" label="币种" width="100"/><el-table-column prop="customerTotal" label="建议报价金额"/><el-table-column label="客户报价" width="150"><template #default="{row}"><el-tag :type="customerQuotationPresentation(row).type">{{ customerQuotationPresentation(row).label }}</el-tag></template></el-table-column><el-table-column v-if="canCreateQuotation" label="操作" width="130"><template #default="{row}"><el-button v-if="row.status==='CONFIRMED'" link type="primary" @click="createCustomerQuotation(row)">{{ Number(row.customerQuotationId||0)>0?'打开报价单':'生成报价单' }}</el-button></template></el-table-column></el-table>
            <el-empty v-if="!confirmedCosts.length" description="采购尚未确认可用于客户报价的成本方案" />
          </el-tab-pane>

          <el-tab-pane v-if="!isSalesView" label="工厂询价" name="rfqs">
            <div class="section-head"><div><h2>工厂询价记录</h2><p>邮件、电话、微信、WhatsApp 或线下询问都在这里统一留痕。</p></div><el-button v-if="canWrite" type="primary" :disabled="!rfqEligibleLines.length" @click="openRFQ">{{ rfqs.length ? '新增工厂询价' : '创建首个工厂询价' }}</el-button></div>
            <el-empty v-if="!rfqs.length" description="尚未联系任何工厂"><el-button v-if="canWrite" type="primary" @click="openRFQ">创建首个工厂询价</el-button></el-empty>
            <el-table :data="rfqs">
              <el-table-column prop="rfqNo" label="询价编号" width="185" />
              <el-table-column label="供应商 / 生产工厂" min-width="230"><template #default="{row}"><strong>{{ row.supplierName }}</strong><small>{{ row.factoryName||'未指定生产工厂' }}</small></template></el-table-column>
              <el-table-column label="询价方式 / 联系人" min-width="210"><template #default="{row}"><strong>{{ channelLabel(row.inquiryChannel) }}</strong><small>{{ row.contactName || '未填写联系人' }} · {{ row.contactValue || row.contactEmail || '—' }}</small></template></el-table-column>
              <el-table-column prop="responseDueAt" label="回复期限" width="130" />
              <el-table-column label="状态" width="130"><template #default="{row}"><el-tag :type="rfqType(row)">{{ rfqLabel(row) }}</el-tag></template></el-table-column>
              <el-table-column label="操作" width="76" align="center" fixed="right"><template #default="{row}"><el-dropdown trigger="click" @command="handleRFQAction($event,row)"><el-button text circle aria-label="操作"><span aria-hidden="true">•••</span></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="download">下载询价单</el-dropdown-item><el-dropdown-item v-if="canWrite" command="edit">修改</el-dropdown-item><el-dropdown-item v-if="canPrice" command="quote" divided>录入新报价</el-dropdown-item><el-dropdown-item v-if="canPrice" command="import">导入报价</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template></el-table-column>
            </el-table>
          </el-tab-pane>

          <el-tab-pane v-if="!isSalesView" label="报价比较" name="quotes">
            <div class="section-head"><div><h2>工厂报价比较</h2><p>按产品分别横向比较各供应商的最新正式报价，避免不同产品和历史版本混在一起。</p></div><div class="quote-sort"><span>排序方式</span><el-select v-model="comparisonSort" style="width:170px"><el-option value="PRICE" label="单价：从低到高"/><el-option value="LEAD_TIME" label="生产周期：从短到长"/><el-option value="MOQ" label="MOQ：从低到高"/></el-select></div></div>
            <div class="quote-summary"><div><b>{{ rfqs.length }}</b><span>已发起 RFQ</span></div><div><b>{{ quotedRfqCount }}</b><span>已收到报价</span></div><div><b>{{ overdueCount }}</b><span>已逾期</span></div></div>
            <el-empty v-if="!quoteLines.length" description="暂无工厂报价；请先在“工厂询价”中录入或导入报价" />
            <div v-else class="quote-compare-groups"><section v-for="group in comparisonQuoteGroups" :key="group.sourcingLineId" class="quote-product-card"><header><div><small>产品行 #{{ sourceLineNo(group.sourcingLineId) }}</small><h3>{{ sourceProduct(group.sourcingLineId) }}</h3><p>客户需求：{{ sourceQuantity(group.sourcingLineId) }} {{ sourceUom(group.sourcingLineId) }}</p></div><div class="quote-product-meta"><el-tag effect="plain">{{ group.rows.length }} 家供应商报价</el-tag><small>{{ comparisonSortLabel }}</small></div></header><el-table :data="group.rows"><el-table-column label="供应商 / 工厂" min-width="190"><template #default="{row}"><strong>{{ row.supplierName }}</strong><small>{{ quoteFactoryName(row) }}</small></template></el-table-column><el-table-column label="最新单价" min-width="205"><template #default="{row}"><strong class="quote-price">{{ row.currency }} {{ row.unitPrice }}/{{ sourceUom(row.sourcingLineId) }}</strong><el-tag v-if="isLowest(row)" size="small" type="success">最低单价</el-tag><small v-if="row.comparePrice&&row.compareCurrency!==row.currency" class="quote-compare">≈ {{ row.compareCurrency }} {{ row.comparePrice }}</small></template></el-table-column><el-table-column label="MOQ" width="145"><template #default="{row}">{{ row.moq || '—' }}<span v-if="row.moq"> {{ sourceUom(row.sourcingLineId) }}</span></template></el-table-column><el-table-column label="生产周期" width="125"><template #default="{row}">{{ row.leadTime || '—' }}<span v-if="row.leadTime"> 天</span></template></el-table-column><el-table-column prop="paymentTerms" label="付款条件" min-width="150"/><el-table-column prop="validUntil" label="有效期" width="120"/><el-table-column label="报价来源" min-width="185"><template #default="{row}"><span>{{ row.supplierQuoteNo }}</span><small>最新版本 V{{ row.versionNo||1 }}</small></template></el-table-column></el-table></section></div>
          </el-tab-pane>

          <el-tab-pane v-if="!isSalesView" label="成本方案" name="costs">
            <div class="section-head"><div><h2>成本与利润方案</h2><p>汇总采购成本、运输与其他费用，形成可确认、可追溯的客户报价依据。</p></div><el-button v-if="canPrice&&confirmedQuoteLines.length&&canStartCostVersion" type="primary" plain @click="openCostScenario">新建成本方案</el-button></div>
            <el-alert v-if="rejectedQuote" type="warning" :closable="false" show-icon style="margin-bottom:12px" :title="`客户已拒绝报价单 ${rejectedQuote.quoteNo}${rejectedQuote.respondNote?`：${rejectedQuote.respondNote}`:''}`"/>
            <el-table :data="costs" @row-click="openCostDetail"><el-table-column label="方案版本" width="210"><template #default="{row}"><strong>V{{ row.versionNo || 1 }}</strong><small>{{ row.scenarioNo }}</small></template></el-table-column><el-table-column prop="currency" label="币种" width="80"/><el-table-column prop="productTotal" label="产品成本"/><el-table-column prop="chargeTotal" label="费用"/><el-table-column prop="customerTotal" label="报价金额"/><el-table-column label="成本状态" width="105"><template #default="{row}"><el-tag :type="costScenarioPresentation(row).type">{{ costScenarioPresentation(row).label }}</el-tag></template></el-table-column><el-table-column label="报价单状态" width="135"><template #default="{row}"><el-tag :type="customerQuotationPresentation(row).type">{{ customerQuotationPresentation(row).label }}</el-tag></template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button v-if="canApprove&&row.status==='DRAFT'&&canStartCostVersion" link type="success" @click.stop="confirmCostScenario(row)">确认方案</el-button></template></el-table-column></el-table>
          </el-tab-pane>

          <el-tab-pane v-if="isSalesView" label="客户报价" name="customerQuote">
            <div class="section-head"><div><h2>报价单</h2><p>由已确认成本方案生成；可在这里打开报价单，并继续下载、发送和跟踪客户反馈。</p></div></div>
            <QuotationsPage embedded :quotation-ids="customerQuotationIds" />
          </el-tab-pane>

          <el-tab-pane label="变更记录" name="changes">
            <div class="section-head"><div><h2>统一变更记录</h2><p>产品规范、RFQ、报价和状态变化在这里按时间追溯。</p></div></div>
            <el-timeline><el-timeline-item v-for="item in changes" :key="item.id" :timestamp="formatTime(item.createdAt)" placement="top"><div class="change"><strong>{{ item.summary }}</strong><p>{{ item.operatorName||'系统' }} · {{ item.section }} / {{ item.action }}</p><p v-if="item.reason">原因：{{ item.reason }}</p></div></el-timeline-item></el-timeline>
            <el-empty v-if="!changes.length" description="暂无变更记录" />
          </el-tab-pane>
        </el-tabs>
      </section>
    </template>

    <el-dialog v-model="rfqOpen" title="新建工厂询价记录" width="680px"><el-alert type="info" :closable="false" title="供应商必须选择；生产工厂可选。系统会直接带入已审核产品，可登记邮件、电话、微信或线下询价。"/><el-form class="rfq-form" label-width="120px"><el-form-item label="供应商 / 工厂" required><SupplierFactorySelect v-model:supplier-id="rfq.supplierId" v-model:factory-id="rfq.factoryId" factory-optional @factory-selected="factorySelected"/></el-form-item><div class="factory-optional-hint">仅在已明确实际生产工厂时选择；向贸易商或供应商总部询价可以留空。</div><el-form-item label="询价渠道" required><el-select v-model="rfq.inquiryChannel" style="width:100%"><el-option v-for="item in inquiryChannels" :key="item.value" :value="item.value" :label="item.label"/></el-select></el-form-item><el-form-item label="联系人"><el-input v-model="rfq.contactName" placeholder="例如：张经理"/></el-form-item><el-form-item v-if="rfq.inquiryChannel==='SYSTEM_EMAIL'" label="联系人邮箱" required><el-input v-model="rfq.contactEmail" placeholder="记录询价联系邮箱"/></el-form-item><el-form-item v-else label="联系方式" required><el-input v-model="rfq.contactValue" placeholder="电话、微信号或联系说明"/></el-form-item><el-form-item label="实际联系时间"><el-date-picker v-model="rfq.contactedAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" placeholder="人工询价时填写"/></el-form-item><el-form-item label="币种" required><el-input v-model="rfq.currency" maxlength="3" placeholder="例如 USD" @input="rfq.currency=String(rfq.currency).toUpperCase()"/></el-form-item><el-form-item label="回复期限" required><el-date-picker v-model="rfq.responseDueAt" value-format="YYYY-MM-DD" :disabled-date="disablePastDate"/></el-form-item><el-form-item label="询价备注"><el-input v-model="rfq.inquiryNote" type="textarea" placeholder="记录谈话要点、约定或下一步动作"/></el-form-item></el-form><template #footer><el-button @click="rfqOpen=false">取消</el-button><el-button type="primary" @click="createRFQ">保存询价记录</el-button></template></el-dialog>
    <el-dialog v-model="editRfqOpen" title="修改工厂询价记录" width="650px"><el-alert type="info" :closable="false" title="可修正询价方式、联系人、联系方式和回复期限；保存时必须填写修改原因。"/><el-form label-width="110px" class="dialog-form"><el-form-item label="询价方式" required><el-select v-model="editRfq.inquiryChannel"><el-option v-for="item in inquiryChannels" :key="item.value" :value="item.value" :label="item.label"/></el-select></el-form-item><el-form-item label="联系人"><el-input v-model="editRfq.contactName"/></el-form-item><el-form-item v-if="editRfq.inquiryChannel==='SYSTEM_EMAIL'" label="联系人邮箱" required><el-input v-model="editRfq.contactEmail"/></el-form-item><el-form-item v-else label="联系方式" required><el-input v-model="editRfq.contactValue" placeholder="电话、微信号、WhatsApp 或联系说明"/></el-form-item><el-form-item v-if="editRfq.inquiryChannel!=='SYSTEM_EMAIL'" label="实际联系时间"><el-date-picker v-model="editRfq.contactedAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ"/></el-form-item><el-form-item label="回复期限" required><el-date-picker v-model="editRfq.responseDueAt" value-format="YYYY-MM-DD" :disabled-date="disablePastDate"/></el-form-item><el-form-item label="询价备注"><el-input v-model="editRfq.inquiryNote" type="textarea"/></el-form-item><el-form-item label="修改原因" required><el-input v-model="editRfq.reason" type="textarea" placeholder="说明为什么需要修改这条询价记录"/></el-form-item></el-form><template #footer><el-button @click="editRfqOpen=false">取消</el-button><el-button type="primary" @click="saveRFQ">保存并记录</el-button></template></el-dialog>

    <el-dialog v-model="quoteOpen" title="录入工厂正式报价" width="1040px"><el-alert type="info" :closable="false" title="保存即表示员工已核实该报价。再次保存会生成新版本，比较页始终只使用最新版本；计量单位来自已审核询盘。"/><el-form inline class="dialog-form"><el-form-item label="报价来源"><el-select v-model="quoteForm.source" style="width:140px"><el-option v-for="item in quoteSources" :key="item.value" :value="item.value" :label="item.label"/></el-select></el-form-item><el-form-item label="币种"><el-input v-model="quoteForm.currency" style="width:90px"/></el-form-item><el-form-item label="报价日期"><el-date-picker v-model="quoteForm.quotedAt" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="有效期至"><el-date-picker v-model="quoteForm.validUntil" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="交期"><el-select v-model="quoteForm.delivery" filterable allow-create default-first-option clearable placeholder="选择或输入交期"><el-option v-for="item in deliveryOptions" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item label="付款条件"><el-select v-model="quoteForm.paymentTerms" filterable allow-create default-first-option clearable placeholder="选择或输入付款条件"><el-option v-for="item in paymentTermOptions" :key="item" :label="item" :value="item"/></el-select></el-form-item></el-form><el-table :data="quoteRows" border><el-table-column prop="product" label="产品" min-width="170"/><el-table-column label="数量" width="130"><template #default="{row}">{{ row.qty }} {{ row.uom }}</template></el-table-column><el-table-column label="单价" min-width="190"><template #default="{row}"><el-input v-model="row.unitPrice" inputmode="decimal"><template #append>{{ quoteForm.currency || 'USD' }}/{{ row.uom }}</template></el-input></template></el-table-column><el-table-column label="MOQ（最小起订量）" min-width="185"><template #default="{row}"><el-input v-model="row.moq" inputmode="decimal"><template #append>{{ row.uom }}</template></el-input></template></el-table-column><el-table-column label="生产周期" min-width="145"><template #default="{row}"><el-input v-model="row.leadTime" inputmode="numeric"><template #append>天</template></el-input></template></el-table-column></el-table><template #footer><el-button @click="quoteOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveQuote">保存正式报价</el-button></template></el-dialog>

    <el-dialog v-model="importOpen" title="导入工厂报价 Excel" width="650px"><el-alert type="info" :closable="false" title="请使用本 RFQ 下载的报价模板，不要修改 RFQ 编号、行 ID、数量或单位。"/><el-form label-width="100px" class="dialog-form"><el-form-item label="报价文件" required><input type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" @change="selectQuoteFile"/></el-form-item><el-form-item label="币种"><el-input v-model="importForm.currency" maxlength="3"/></el-form-item><el-form-item label="报价日期"><el-date-picker v-model="importForm.quotedAt" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="有效期至"><el-date-picker v-model="importForm.validUntil" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="交期"><el-select v-model="importForm.delivery" filterable allow-create default-first-option clearable placeholder="选择或输入交期"><el-option v-for="item in deliveryOptions" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item label="付款条件"><el-select v-model="importForm.paymentTerms" filterable allow-create default-first-option clearable placeholder="选择或输入付款条件"><el-option v-for="item in paymentTermOptions" :key="item" :label="item" :value="item"/></el-select></el-form-item></el-form><template #footer><el-button @click="importOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="importQuote">导入报价</el-button></template></el-dialog>

