function specificationSummary(extracted:any){const hidden=new Set(['product','quantity','quantity_unit']);const parts=reviewFields.value.filter(field=>!hidden.has(field.key)).map(field=>{const value=readTemplateField(extracted,field.key);return value?`${field.label}: ${value}`:''}).filter(Boolean);return parts.join(' · ')||'暂无其他规格'}
function formatTime(v:string){return v?new Date(v).toLocaleString():'—'}function sourceLineNo(v:string){return detail.value?.lines.find((x:any)=>String(x.id)===String(v))?.lineNo||v}function isOverdue(x:any){return ['SENT','PARTIALLY_QUOTED'].includes(x.status)&&x.responseDueAt&&new Date(x.responseDueAt).getTime()<Date.now()}function rfqLabel(x:any){return isOverdue(x)?'已逾期':({DRAFT:'草稿',SENT:'已发送',PARTIALLY_QUOTED:'部分报价',QUOTED:'已报价',CLOSED:'已关闭',CANCELLED:'已取消'} as any)[x.status]||x.status}function rfqType(x:any){return isOverdue(x)?'danger':x.status==='QUOTED'?'success':'info'}function openSourceMail(){void router.push({path:'/emails',query:{message:detail.value?.sourceMailId}})}function openSourceFile(){if(detail.value?.sourceFileUrl)window.open(detail.value.sourceFileUrl,'_blank','noopener')}function disablePastDate(date:Date){const today=new Date();today.setHours(0,0,0,0);return date.getTime()<today.getTime()}function validEmail(value:string){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())}
function openRFQ(){Object.assign(rfq,{supplierId:'',factoryId:'',factoryCode:'',factoryName:'',inquiryChannel:'SYSTEM_EMAIL',contactName:'',contactEmail:'',contactValue:'',contactedAt:'',inquiryNote:'',currency:'USD',responseDueAt:''});rfqOpen.value=true}async function factorySelected(factory:any){rfq.factoryCode=factory?.code||'';rfq.factoryName=factory?.nameZh||factory?.nameEn||'';rfq.contactEmail='';if(factory?.id){const d=await get<any>(`/factories/${factory.id}/contacts`);const primary=(d.contacts||[]).find((x:any)=>x.isPrimary&&x.status==='ACTIVE');rfq.contactName=primary?.name||'';rfq.contactEmail=primary?.email||'';rfq.contactValue=primary?.phone||''}}async function createRFQ(){if(!rfq.supplierId){ElMessage.warning('请选择供应商');return}if(rfq.inquiryChannel==='SYSTEM_EMAIL'&&!validEmail(rfq.contactEmail)){ElMessage.warning('邮件询价必须填写有效邮箱');return}if(rfq.inquiryChannel!=='SYSTEM_EMAIL'&&!String(rfq.contactValue).trim()){ElMessage.warning('请填写人工询价的联系方式');return}if(!/^[A-Z]{3}$/.test(String(rfq.currency).trim().toUpperCase())){ElMessage.warning('币种必须是 3 位代码，例如 USD 或 CNY');return}if(!rfq.responseDueAt){ElMessage.warning('请选择回复期限');return}const lineIds=rfqEligibleLines.value.map((line:any)=>Number(line.id));if(!lineIds.length){ElMessage.warning('询盘没有可用于询价的产品明细');return}const sameTarget=rfqs.value.filter(item=>Number(item.supplierId)===Number(rfq.supplierId)&&Number(item.factoryId||0)===Number(rfq.factoryId||0)&&!['CANCELLED','CLOSED'].includes(item.status));if(sameTarget.length){try{await ElMessageBox.confirm(`该供应商${rfq.factoryId?'及工厂':'（未指定工厂）'}已有 ${sameTarget.length} 条有效询价记录。若只是修改联系人或期限，请取消并编辑原记录；仅在确需新一轮询价时继续。`,'发现可能重复的询价',{confirmButtonText:'仍然创建新一轮',cancelButtonText:'返回检查',type:'warning'})}catch(action){if(isDialogDismissed(action))return;throw action}}const nextRound=sameTarget.reduce((max,item)=>Math.max(max,Number(item.roundNo||1)),0)+1;await post(`/sourcing-cases/${id}/factory-rfqs`,{supplier_id:Number(rfq.supplierId),factory_id:Number(rfq.factoryId||0),factory_code:rfq.factoryCode,factory_name:rfq.factoryName,inquiry_channel:rfq.inquiryChannel,contact_name:rfq.contactName,contact_email:rfq.contactEmail,contact_value:rfq.contactValue,contacted_at:rfq.contactedAt,inquiry_note:rfq.inquiryNote,round_no:nextRound,currency:String(rfq.currency).trim().toUpperCase(),response_due_at:rfq.responseDueAt,sourcing_line_ids:lineIds});rfqOpen.value=false;await load();ElMessage.success(sameTarget.length?'新一轮询价记录已创建':'询价记录已创建')}
function openEditRFQ(row:any){editingRfq.value=row;Object.assign(editRfq,{inquiryChannel:row.inquiryChannel||'SYSTEM_EMAIL',contactName:row.contactName||'',contactEmail:row.contactEmail||'',contactValue:row.contactValue||'',contactedAt:row.contactedAt||'',inquiryNote:row.inquiryNote||'',responseDueAt:row.responseDueAt,reason:''});editRfqOpen.value=true}async function saveRFQ(){if(editRfq.inquiryChannel==='SYSTEM_EMAIL'&&!validEmail(editRfq.contactEmail)){ElMessage.warning('邮件询价必须填写有效邮箱');return}if(editRfq.inquiryChannel!=='SYSTEM_EMAIL'&&!String(editRfq.contactValue).trim()){ElMessage.warning('请填写人工询价的联系方式');return}if(!editRfq.responseDueAt){ElMessage.warning('请选择工厂回复期限');return}if(!String(editRfq.reason).trim()){ElMessage.warning('请填写修改原因');return}const isEmail=editRfq.inquiryChannel==='SYSTEM_EMAIL';await put(`/factory-rfqs/${editingRfq.value?.id}`,{inquiry_channel:editRfq.inquiryChannel,contact_name:editRfq.contactName,contact_email:isEmail?editRfq.contactEmail:'',contact_value:isEmail?'':editRfq.contactValue,contacted_at:isEmail?'':editRfq.contactedAt,inquiry_note:editRfq.inquiryNote,response_due_at:editRfq.responseDueAt,reason:editRfq.reason});editRfqOpen.value=false;await load();ElMessage.success('询价记录已修改并留下变更记录')}
async function downloadRFQ(row:any){const f=await download(`/factory-rfqs/${row.id}/workbook`);saveBlob(f.blob,f.fileName||`${row.rfqNo}.xlsx`)}
function handleRFQAction(command:string,row:any){if(command==='download'){void downloadRFQ(row);return}if(command==='edit'){openEditRFQ(row);return}if(command==='quote'){openQuote(row);return}if(command==='import')openImport(row)}

// openQuote 根据 RFQ 包含的产品行创建录入表格，避免员工把报价填到错误产品上。
function openQuote(row:any){quotingRfq.value=row;Object.assign(quoteForm,{currency:row.currency||'USD',quotedAt:'',validUntil:'',delivery:'',paymentTerms:'',source:row.inquiryChannel==='SYSTEM_EMAIL'?'MANUAL':row.inquiryChannel||'MANUAL',confirmationStatus:'WRITTEN_CONFIRMED'});const included=new Set((row.sourcingLineIds||[]).map(String));quoteRows.value=(detail.value?.lines||[]).filter((line:any)=>included.has(String(line.id))).map((line:any)=>({sourcingLineId:line.id,product:line.extracted.product,qty:line.extracted.quantity,uom:String(line.extracted.quantityUnit||'').trim().toUpperCase(),unitPrice:'',moq:'',leadTime:''}));quoteOpen.value=true}
async function saveQuote(){if(!quotingRfq.value||quoteRows.value.some(row=>row.unitPrice===''||Number(row.unitPrice)<0)){ElMessage.warning('请填写全部产品的有效单价');return}saving.value=true;try{await post(`/factory-rfqs/${quotingRfq.value.id}/supplier-quotes`,{quoted_at:quoteForm.quotedAt,valid_until:quoteForm.validUntil,currency:quoteForm.currency,payment_terms:quoteForm.paymentTerms,delivery:quoteForm.delivery,source:quoteForm.source,confirmation_status:'WRITTEN_CONFIRMED',lines:quoteRows.value.map(row=>({sourcing_line_id:Number(row.sourcingLineId),qty:row.qty,unit_price:row.unitPrice,moq:row.moq,lead_time:row.leadTime}))});quoteOpen.value=false;await load();ElMessage.success('正式报价新版本已保存')}finally{saving.value=false}}
function openImport(row:any){importingRfq.value=row;quoteFile.value=null;Object.assign(importForm,{currency:row.currency||'USD',quotedAt:'',validUntil:'',delivery:'',paymentTerms:''});importOpen.value=true}
function selectQuoteFile(event:Event){quoteFile.value=(event.target as HTMLInputElement).files?.[0]??null}
async function fileBase64(file:File){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(binary)}
async function importQuote(){if(!importingRfq.value||!quoteFile.value){ElMessage.warning('请选择工厂回传的 XLSX 报价文件');return}if(quoteFile.value.size>2*1024*1024){ElMessage.warning('报价文件不能超过 2 MB');return}saving.value=true;try{await post(`/factory-rfqs/${importingRfq.value.id}/supplier-quotes/import`,{file_data:await fileBase64(quoteFile.value),quoted_at:importForm.quotedAt,valid_until:importForm.validUntil,currency:importForm.currency,payment_terms:importForm.paymentTerms,delivery:importForm.delivery});importOpen.value=false;await load();ElMessage.success('工厂报价已导入')}finally{saving.value=false}}

function quotesForLine(lineID:string){return confirmedComparisonQuoteLines.value.filter(item=>String(item.sourcingLineId)===String(lineID))}function isLowest(row:any){const group=confirmedComparisonQuoteLines.value.filter(x=>String(x.sourcingLineId)===String(row.sourcingLineId));if(group.length>1&&group.every(x=>x.comparePrice))return Number(row.comparePrice)===Math.min(...group.map(x=>Number(x.comparePrice)));const values=group.filter(x=>x.currency===row.currency).map(x=>Number(x.unitPrice));return values.length>1&&Number(row.unitPrice)===Math.min(...values)}function quoteRowClass({row}:any){return (row.confirmationStatus||'WRITTEN_CONFIRMED')!=='WRITTEN_CONFIRMED'?'quote-pending':''}
function openCostScenario(){Object.assign(costForm,{currency:'USD',allocationBasis:'TONS',marginType:'PERCENT',marginValue:'8'});costSelections.value=rfqEligibleLines.value.map((line:any)=>({sourcingLineId:line.id,lineNo:line.lineNo,product:line.extracted.product,quoteLineId:quotesForLine(line.id)[0]?.quoteLineId||''}));costCharges.splice(0);addCharge();costOpen.value=true}
function chargeTypeLabel(value:string){return chargeTypeLabels[value]||value}
function chargeBasisLabel(value:string){return chargeBasisLabels[value]||value}
function addCharge(){costCharges.push({chargeType:'OTHER',customChargeName:'',basis:'FIXED',amount:'',currency:costForm.currency,source:''})}
async function createCostScenario(){if(costSelections.value.some(line=>!line.quoteLineId)){ElMessage.warning('请为每条产品选择一个工厂报价');return}if(costCharges.some(item=>!String(item.chargeType||'').trim()||item.chargeType==='OTHER'&&!String(item.customChargeName||'').trim()||item.amount===''||Number(item.amount)<0)){ElMessage.warning('请填写具体费用名称和有效金额');return}saving.value=true;try{await post(`/sourcing-cases/${id}/cost-scenarios`,{currency:costForm.currency,allocation_basis:costForm.allocationBasis,margin_type:costForm.marginType,margin_value:costForm.marginValue,selections:costSelections.value.map(line=>({sourcing_line_id:Number(line.sourcingLineId),supplier_quote_line_id:Number(line.quoteLineId)})),charges:costCharges.map(item=>({charge_type:item.chargeType,description:item.chargeType==='OTHER'?String(item.customChargeName).trim():'',basis:item.basis,amount:item.amount,currency:item.currency,source:item.source}))});costOpen.value=false;await load();ElMessage.success('成本方案已创建')}finally{saving.value=false}}
async function openCostDetail(row:any){costDetail.value=(await get<any>(`/cost-scenarios/${row.id}`)).costScenario;costDetailOpen.value=true}
async function confirmCostScenario(row:any){const {value}=await ElMessageBox.prompt('请填写选择该方案的原因，便于后续审批与业务追溯。可说明价格、交期、MOQ、付款条件、质量或供应稳定性等因素。','确认成本方案（中标）',{inputPlaceholder:'请输入选择该方案的主要原因',inputValidator:(v:string)=>!!v.trim()||'请填写选择说明'}).catch(()=>({value:''}));if(!value)return;await post(`/cost-scenarios/${row.id}/confirm`,{reason:value});await load();ElMessage.success('成本方案已确认，选择说明已写入变更记录')}
async function createCustomerQuotation(row:any){if(Number(row.customerQuotationId||0)>0){await router.push(`/sales/inquiries/${id}`);tab.value='customerQuote';return}if(!Number(detail.value?.customerId||0)){customers.value=(await get<any>('/customers',{page_size:200,status:'ACTIVE'})).customers||[];pendingCostScenario.value=row;mappedCustomerId.value='';customerMapOpen.value=true;return}await performCreateCustomerQuotation(row,detail.value?.customerId)}
async function submitMappedCustomer(){if(!pendingCostScenario.value||!mappedCustomerId.value){ElMessage.warning('请选择内部客户');return}customerMapOpen.value=false;await performCreateCustomerQuotation(pendingCostScenario.value,mappedCustomerId.value)}
async function performCreateCustomerQuotation(row:any,customerID:string){try{await ElMessageBox.confirm(`确认根据成本方案 V${row.versionNo||1}（${row.scenarioNo||'已确认方案'}）生成客户报价单？生成后将进入销售模块继续编辑报价内容。`,'生成客户报价单',{confirmButtonText:'确认生成',cancelButtonText:'取消',type:'warning'})}catch(error){if(isDialogDismissed(error))return;throw error}saving.value=true;try{const response=await post<any>(`/cost-scenarios/${row.id}/create-customer-quotation`,{customer_id:Number(customerID)});ElMessage.success(`报价单 ${response.quoteNo} 已生成`);await load();await router.push(`/sales/inquiries/${id}`);tab.value='customerQuote'}finally{saving.value=false}}
onMounted(load)
</script>
