s__item:hover){color:var(--accent)}.section-head{display:flex;justify-content:space-between;align-items:center;margin:10px 0 16px}.section-head h2{margin:0;color:#172b4d;font-size:19px}.section-head p{margin:5px 0 0;color:#6b778c}.el-table small{display:block;color:#8993a4;margin-top:4px}.missing-tag{margin-top:6px}.quote-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:16px}.quote-summary div{padding:16px;border:1px solid #e3e7ec;border-radius:8px;background:#fafbfc}.quote-summary b,.quote-summary span{display:block}.quote-summary b{font-size:24px;color:var(--accent)}.change{padding:13px;border:1px solid #e1e8ee;border-radius:9px}.change p{margin:5px 0 0;color:#768696}.review-form,.dialog-form{margin-top:14px}.review-form .el-select{width:100%}.review-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}.cost-head{margin-top:18px}@media(max-width:850px){.detail-page{padding:16px}.hero,.section-head{align-items:flex-start;gap:12px;flex-direction:column}.progress-card{overflow:auto}.stage{min-width:140px}.progress-card aside{display:none}.review-grid{grid-template-columns:1fr}}
:deep(.quote-pending){background:#fff9ed}:deep(.quote-pending td){color:#8a6320}
.quote-sort{display:flex;align-items:center;gap:10px;color:#66798a;font-size:14px}.quote-compare-groups{display:grid;gap:16px}.quote-product-card{overflow:hidden;border:1px solid #dfe7ec;border-radius:12px;background:#fff}.quote-product-card>header{display:flex;justify-content:space-between;align-items:center;padding:15px 18px;background:#f3f9f8;border-bottom:1px solid #e0e9ec}.quote-product-card h3{margin:3px 0;color:#17324d;font-size:17px}.quote-product-card p,.quote-product-card small{margin:0;color:#718395}.quote-product-meta{display:flex;align-items:flex-end;gap:6px;flex-direction:column}.quote-price{margin-right:8px;color:#17324d}.quote-compare{display:block;color:#8a9aa8;font-size:12px}.quote-product-card :deep(.el-table__row:hover>td){background:#f7fbfb!important}
.perspective-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.perspective-summary>div{display:flex;flex-direction:column;gap:7px;padding:18px;border:1px solid #dfe8e6;border-radius:10px;background:#f7fbfa}.perspective-summary small{color:#718395}.perspective-summary strong{color:#17324d;font-size:20px}@media(max-width:850px){.perspective-summary{grid-template-columns:1fr 1fr}}
.charge-type-editor{display:grid;gap:6px}
.detail-page--sales{--accent:#76546f;--accent-soft:#f6f1f5}
